command:
/**
 * DarkSpace Planet & Settlement Generator
 * Rolls planetary biome and settlement type for frontier sandbox exploration.
 */
const pack = game.packs.get("darkspace.rollable-tables");
if (!pack) {
  ui.notifications.error("DarkSpace rollable-tables pack not found.");
} else {
  const biomeTable = await pack.getDocument("dsTabPlanetBiome");
  const settTable = await pack.getDocument("dsTabSettlement");

  const biome = (await biomeTable?.draw({ displayChat: false }))?.results[0]?.text || "Arid / Desert";
  const settlement = (await settTable?.draw({ displayChat: false }))?.results[0]?.text || "Mining Outpost";

  const content = `
    <div style="border: 1px solid #26a69a; background: rgba(10, 25, 25, 0.95); color: #e0f2f1; padding: 12px; border-radius: 6px;">
      <h3 style="margin: 0 0 8px 0; color: #80cbc4; border-bottom: 1px solid #26a69a; padding-bottom: 4px;">
        <i class="fas fa-globe"></i> Planetary Reconnaissance
      </h3>
      <p style="margin: 6px 0;"><b>Primary Biome:</b> ${biome}</p>
      <p style="margin: 6px 0;"><b>Settlement / Habitation:</b> ${settlement}</p>
    </div>
  `;

  await ChatMessage.create({
    user: game.user._id,
    speaker: { alias: "Orbital Sensor Suite" },
    content: content
  });
}
